create or replace function public.app_8950_bookings_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or public.app_8950_is_admin() then return new; end if;
  if tg_op = 'INSERT' then
    new.customer_id := auth.uid();
    new.status := 'جديد';
  else
    new.customer_id := old.customer_id;
    new.status := old.status;
  end if;
  return new;
end $$;
drop trigger if exists app_8950_bookings_guard on public.app_8950_bookings;
