create or replace function public.app_8950_bookings_notify() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    insert into public.app_8950_notifications (to_role, title, body, data, created_by) values ('admin', 'الحجوزات: جديد', concat_ws(' · ', new.place::text, new.status::text), jsonb_build_object('table', 'bookings', 'id', new.id), auth.uid());
  elsif tg_op = 'UPDATE' then
    if new.customer_id is not null and new.customer_id is distinct from auth.uid() then insert into public.app_8950_notifications (to_user, title, body, data, created_by) values (new.customer_id, 'الحجوزات: تحديث', concat_ws(' · ', new.place::text, new.status::text), jsonb_build_object('table', 'bookings', 'id', new.id), auth.uid()); end if;
  end if;
  return new;
end $$;
drop trigger if exists app_8950_bookings_notify on public.app_8950_bookings;
create trigger app_8950_bookings_notify after insert or update on public.app_8950_bookings for each row execute function public.app_8950_bookings_notify();

create or replace function public.app_8950_stats() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.app_8950_is_admin() then raise exception 'admins only'; end if;
  return jsonb_build_object('places', (select count(*) from public.app_8950_places), 'bookings', (select count(*) from public.app_8950_bookings), '_customers', (select count(*) from public.app_8950_profiles where role = 'customer'));
end $$;
grant execute on function public.app_8950_stats() to authenticated;

